-- Manual media is separate from scraped content: catalog updates never overwrite it.
ALTER TABLE schools ADD COLUMN logo_url varchar(2000);
ALTER TABLE schools ADD COLUMN logo_credit jsonb NOT NULL DEFAULT '{}'::jsonb;
ALTER TABLE schools ADD COLUMN campus_photos jsonb NOT NULL DEFAULT '[]'::jsonb
  CHECK (jsonb_typeof(campus_photos) = 'array' AND jsonb_array_length(campus_photos) <= 10);

-- Initial reviewed media for the nine existing institutions. Never re-seed on
-- server startup. Future manual edits belong to the administrator.
UPDATE schools s SET logo_url = media."logoUrl", logo_credit = media."logoCredit", campus_photos = media."campusPhotos"
