k","licenseUrl":""},"campusPhotos":[{"url":"https://www.sti.edu/cms/images/school/all/global.jpg","caption":"STI Academic Center — Global City","credit":"STI Education Services Group","sourceUrl":"https://www.sti.edu/campuses-details.asp?campus_id=R0xP","license":"Official campus image — rights reserved","licenseUrl":""},{"url":"https://www.sti.edu/cms/images/events/2009/sti_unveils/front_306x191.jpg","caption":"STI Global City Academic Center (2009 archival photo)","credit":"STI Education Services Group","sourceUrl":"https://www.sti.edu/newsarticledetail1.asp?i=MTI3&p=c3RpX29mZmljaWFsbHlfdW52ZWlsc190aGVfc3RpX2FjYWRlbWljX2NlbnRlcg%3D%3D","license":"Official campus image — rights reserved","licenseUrl":""}]}]'::jsonb)
